			updateBox.append(updateStatus, updateButton);
			const platform = getUpdatePlatform();
			const installedVersion = envInfo.scriptVersion;
			let updateCheckRunning = false;
			const checkUpdates = async (force = false) => {
				if (updateCheckRunning) return;
				updateCheckRunning = true;
				updateButton.setAttribute("disabled", "true");
				updateStatus.textContent = localizationProvider.get("VOTCheckingUpdates");
				updateBox.querySelectorAll("a, small").forEach((node) => {
					node.remove();
				});
				try {
					const result = await checkForUpdate(installedVersion, platform, force);
					if (!result) {
						updateStatus.textContent = localizationProvider.get("VOTLatestVersion");
						return;
					}
					updateStatus.textContent = localizationProvider.get("VOTUpdateAvailable").replace("{0}", () => result.version);
					const downloads = result.complete ? result.assets : [];
					if (downloads.length) for (const asset of downloads) {
						const link = document.createElement("a");
						link.href = asset.url;
						link.target = "_blank";
						link.rel = "noopener noreferrer";
						link.textContent = localizationProvider.get("VOTDownloadUpdate");
						link.style.display = "block";
						updateBox.append(link);
					}
					else {
						const link = document.createElement("a");
						link.href = result.releaseUrl || "https://github.com/Acobat12/voice-over-translation-direct/releases/latest";
						link.target = "_blank";
						link.rel = "noopener noreferrer";
						link.textContent = localizationProvider.get("VOTOpenRelease");
						updateBox.append(link);
						if (platform === "safari") updateStatus.textContent += localizationProvider.get("VOTSafariZipMissing");
					}
					const instruction = document.createElement("small");
					instruction.textContent = platform === "chrome" ? localizationProvider.get("VOTUpdateChrome") : platform === "firefox" ? localizationProvider.get("VOTUpdateFirefox") : platform === "safari" ? localizationProvider.get("VOTUpdateSafari") : localizationProvider.get("VOTUpdateUserscript");
					instruction.style.display = "block";
					updateBox.append(instruction);
				} catch {
					updateStatus.textContent = localizationProvider.get("VOTUpdateFailed");
				} finally {
					updateCheckRunning = false;
					updateButton.removeAttribute("disabled");
				}
			};
			updateButton.addEventListener("click", () => {
				checkUpdates(true);
			});
			checkUpdates();
			aboutSection.content.append(versionInfo.container, updateBox, authorsInfo.container, loaderInfo.container, userBrowserInfo.container, localeInfo.container, updateLocaleFilesButton);
			this.dialog.footerContainer.append(this.bugReportButton, this.resetSettingsButton);
			this.initialized = true;
